#!/usr/bin/env python3
"""Read-only literal UTF-8 search confined to a caller-approved root."""
import json
import os
import stat
import sys
from pathlib import Path


class InvalidInput(Exception):
    pass


def search(data):
    """Return matching lines, or {'error': 'invalid_input'}."""
    invalid = {'error': 'invalid_input'}
    if not isinstance(data, dict) or set(data) != {'root', 'query', 'path'}:
        return invalid
    if any(not isinstance(data[k], str) for k in data):
        return invalid
    if not data['root'] or not data['query'] or not data['path']:
        return invalid
    if '\x00' in data['root'] or '\x00' in data['path']:
        return invalid

    try:
        # Fail closed on platforms without descriptor-relative traversal.
        if not hasattr(os, 'O_NOFOLLOW') or os.open not in os.supports_dir_fd:
            raise InvalidInput()
        root = str(Path(data['root']).resolve(strict=True))
        target = os.path.abspath(os.path.join(root, data['path']))
        if os.path.commonpath([root, target]) != root:
            raise InvalidInput()
        relative = os.path.relpath(target, root)
        parts = [] if relative == '.' else relative.split(os.sep)
        flags = os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK
        directory_flags = flags | os.O_DIRECTORY
        matches = []

        def read_file(fd, name):
            # Decode the entire file before adding any matches. Non-UTF-8
            # files are skipped, including any otherwise valid prefix.
            with os.fdopen(os.dup(fd), 'rb') as stream:
                raw = stream.read()
            try:
                content = raw.decode('utf-8')
            except UnicodeDecodeError:
                return
            # Treat LF, CRLF, and CR as line endings; preserve other text.
            content = content.replace('\r\n', '\n').replace('\r', '\n')
            lines = content.split('\n')
            if lines and lines[-1] == '':
                lines.pop()
            for number, line in enumerate(lines, 1):
                if data['query'] in line:
                    matches.append({'path': name, 'line': number, 'text': line})

        def visit(fd, name):
            mode = os.fstat(fd).st_mode
            if stat.S_ISREG(mode):
                read_file(fd, name)
                return
            if not stat.S_ISDIR(mode):
                raise InvalidInput()
            with os.scandir(fd) as entries:
                names = sorted(entry.name for entry in entries)
            for child in names:
                mode = os.stat(child, dir_fd=fd, follow_symlinks=False).st_mode
                # Never follow symlinks or read devices, sockets, or FIFOs.
                if not (stat.S_ISDIR(mode) or stat.S_ISREG(mode)):
                    continue
                child_flags = directory_flags if stat.S_ISDIR(mode) else flags
                child_fd = os.open(child, child_flags, dir_fd=fd)
                try:
                    child_name = name + '/' + child if name else child
                    visit(child_fd, child_name)
                finally:
                    os.close(child_fd)

        fd = os.open(root, directory_flags)
        try:
            for index, component in enumerate(parts):
                next_flags = directory_flags if index < len(parts) - 1 else flags
                next_fd = os.open(component, next_flags, dir_fd=fd)
                os.close(fd)
                fd = next_fd
            visit(fd, '/'.join(parts))
        finally:
            os.close(fd)
        matches.sort(key=lambda item: (item['path'], item['line']))
        return {'matches': matches}
    except (InvalidInput, OSError, ValueError, RuntimeError, NotImplementedError):
        return invalid


def main():
    try:
        def unique_object(pairs):
            result = {}
            for key, value in pairs:
                if key in result:
                    raise ValueError('duplicate key')
                result[key] = value
            return result
        data = json.load(sys.stdin, object_pairs_hook=unique_object)
        result = search(data)
    except (ValueError, UnicodeError):
        result = {'error': 'invalid_input'}
    print(json.dumps(result, ensure_ascii=True))


if __name__ == '__main__':
    main()
